head.script:
scwin.onpageload = function() {
    scwin.group = 5;
    scwin.toggleRow = {};

    var data = [];
    for (var i = 0; i < 100; i++) {
        for (var j = 0; j < 6; j++) {
            if (j === 2) {
                data.push(i + "_" + j);
            } else {
                data.push(Math.floor(j / 2) * 100 + Math.floor(i / (j + scwin.group)));
            }
            //data.push(j * 100 + (i % 5));
        }
    }
    dataList1.setData(data);
    dataList2.setData(["bycol", "bycol", "byrow", "byrow", "bycolrec", "bycolrec", "byrowrec", "byrowrec", "byrestriccol", "byrestriccol", "byrestricrow", "byrestricrow", "never", "never"]);
};
scwin.onpageunload = function() {};
scwin.gridView1_oncellclick = function(row, col) {
    if (col !== 0) {
        return;
    }
    var topRowIndex = Math.floor(row / scwin.group) * scwin.group;
    var flag = false;
    if (scwin.toggleRow[topRowIndex] === true) {
        flag = true;
        scwin.toggleRow[topRowIndex] = false;
    } else {
        scwin.toggleRow[topRowIndex] = true;
    }
    for (var i = 1; i < scwin.group; i++) {
        gridView1.setRowVisible(topRowIndex + i, flag);
    }
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행 후 그리드뷰에서 마우스 스크롤을 아래로 이동한다.(끝까지 이동 시 2번 스크롤이동)
    //1. After running the sample file, move the mouse scroll down in the grid view (scroll 2 times to the end)
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_scrollY_div').scrollTop = 1000");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_scrollY_div').scrollTop = 2000");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_cell_5_0').click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_scrollY_div').scrollTop = 2000");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify step 1. 그리드뷰의 7번, 8번, 9번 row가 정상적으로 comMerge되어 보여진다.(이전에는 7,8,9번 row가 comMerge되어지지 않고 라인이 보여짐)
    //1. The rows 7, 8, and 9 of the grid view are normally comma-delimited (previously rows 7, 8, and 9 are not comma-delimited)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('gridView1_headerRowNumber_bodyRow_0').innerText == '87'", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
